import{_ as a,o as n,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const y=JSON.parse('{"title":"Контекст: this","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js/main/context.md","filePath":"wiki/dev-commit/js/js/main/context.md"}'),t={name:"wiki/dev-commit/js/js/main/context.md"};function e(p,s,i,c,r,d){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="контекст-this" tabindex="-1">Контекст: this <a class="header-anchor" href="#контекст-this" aria-label="Permalink to &quot;Контекст: this&quot;">​</a></h1><ul><li><strong>Контекст</strong> - объект, который получит функция на момент выполнения своего кода</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> foo</span><span style="color:#383A42;">() { console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(</span><span style="color:#E45649;">this</span><span style="color:#383A42;">); }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Глобальный контекст</span></span>
<span class="line"><span style="color:#4078F2;">foo</span><span style="color:#383A42;">();</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// =&gt; window || undefined</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Контекст объекта</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> obj</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> { </span><span style="color:#E45649;">name</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;Tony&#39;</span><span style="color:#383A42;"> }</span></span>
<span class="line"><span style="color:#383A42;">foo.</span><span style="color:#4078F2;">call</span><span style="color:#383A42;">(obj);</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// =&gt; { name: &#39;Tony&#39; }</span></span></code></pre></div><hr><ul><li><strong>Контекст выполнения (Execution Context)</strong> - служебная информация, которая соответствует текущему запуску функции. Она включает в себя локальные переменные функции и конкретное место в коде, на котором находится интерпретатор. У каждого вызова функции свой «контекст выполнения» и он всегда разный в зависимости от того как функция была вызвана</li><li>Контекст бывает либо глобальным, с которого начинается исполнения скрипта, либо контекстом выполнения вызова, который начинается с момента входа в тело функции</li><li>В каждый момент времени активен только один контекст выполнения. Именно поэтому Javascript называют “однопоточным”, имея ввиду, что только одна инструкция исполняется в один момент времени. Типичный браузер отслеживает контексты выполнения с помощью стека</li><li><strong>Контекст вызова функции</strong> - тот объект который ее вызывает</li></ul><ul><li><p><strong>this</strong> - ссылка на текущий контекст вызова (на текущий объект с которым произошло событие). Определяется в момент вызова функции</p></li><li><p>this - обращение к контексту функции. Функция вызывается в контексте объекта, this ссылка на этот объекта</p></li><li><p>this зависит от того как вызвана функция</p></li><li><p>Любая функция может иметь в себе this. Если функция использует this - это подразумевает работу с объектом</p></li><li><p>this - это текущий объект при вызове «через точку» и новый объект при конструировании через new</p></li><li><p>Функции не привязаны к своему контексту this</p></li><li><p>В глобальном контексте - на глобальный объект</p></li><li><p>В функциональном контексте - на контекст, откуда функция вызвана</p></li><li><p>В функции, обрабатывающей событие DOM - на DOM элемент, который вызвал событие</p></li></ul><h2 id="значение-this-устанавливается-в-зависимости-от-того-как-вызвана-функция" tabindex="-1">Значение this устанавливается в зависимости от того, как вызвана функция <a class="header-anchor" href="#значение-this-устанавливается-в-зависимости-от-того-как-вызвана-функция" aria-label="Permalink to &quot;Значение this устанавливается в зависимости от того, как вызвана функция&quot;">​</a></h2><h3 id="_1-при-вызове-функции-как-метода" tabindex="-1">1. При вызове функции как метода <a class="header-anchor" href="#_1-при-вызове-функции-как-метода" aria-label="Permalink to &quot;1. При вызове функции как метода&quot;">​</a></h3><p>this = obj</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">obj.</span><span style="color:#4078F2;">func</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">...</span><span style="color:#383A42;">)</span></span>
<span class="line"><span style="color:#383A42;">obj[</span><span style="color:#50A14F;">&quot;func&quot;</span><span style="color:#383A42;">](</span><span style="color:#0184BC;">...</span><span style="color:#383A42;">)</span></span></code></pre></div><h3 id="_2-при-обычном-вызове" tabindex="-1">2. При обычном вызове <a class="header-anchor" href="#_2-при-обычном-вызове" aria-label="Permalink to &quot;2. При обычном вызове&quot;">​</a></h3><p>this = window (ES3) /undefined (ES5)</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">func</span><span style="color:#383A42;">(</span><span style="color:#0184BC;">...</span><span style="color:#383A42;">)</span></span></code></pre></div><hr><h3 id="_3-в-new" tabindex="-1">3. В new <a class="header-anchor" href="#_3-в-new" aria-label="Permalink to &quot;3. В new&quot;">​</a></h3><p>this = {} (новый объект)</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">new</span><span style="color:#4078F2;"> func</span><span style="color:#383A42;">()</span></span></code></pre></div><h3 id="_4-явное-указание" tabindex="-1">4. Явное указание <a class="header-anchor" href="#_4-явное-указание" aria-label="Permalink to &quot;4. Явное указание&quot;">​</a></h3><p>this = context (явная передача)</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">func.</span><span style="color:#4078F2;">apply</span><span style="color:#383A42;">(context, args)</span></span>
<span class="line"><span style="color:#383A42;">func.</span><span style="color:#4078F2;">call</span><span style="color:#383A42;">(context, arg1, arg2, </span><span style="color:#0184BC;">...</span><span style="color:#383A42;">)</span></span></code></pre></div><h2 id="_4-способа-вызова-this" tabindex="-1">4 способа вызова this <a class="header-anchor" href="#_4-способа-вызова-this" aria-label="Permalink to &quot;4 способа вызова this&quot;">​</a></h2><ol><li>bind call apply</li><li>new конструктор</li><li>функция</li><li>объект</li></ol>`,22)])])}const u=a(t,[["render",e]]);export{y as __pageData,u as default};
